    #[allow(unused_variables)]
    pub unsafe fn cascade_property(
        declaration: &PropertyDeclaration,
        context: &mut computed::Context,
    ) {
        context.for_non_inherited_property = true;
        debug_assert_eq!(
            declaration.id().as_longhand().unwrap(),
            LonghandId::MaskComposite,
        );
        let specified_value = match *declaration {
            PropertyDeclaration::CSSWideKeyword(ref wk) => {
                match wk.keyword {
                    CSSWideKeyword::Unset |
                    CSSWideKeyword::Initial => {
                            declaration.debug_crash("Unexpected initial or unset for non-inherited property");
                    },
                    CSSWideKeyword::Inherit => {
                            context.rule_cache_conditions.borrow_mut().set_uncacheable();
                            context.builder.inherit_mask_composite();
                    }
                    CSSWideKeyword::RevertRule |
                    CSSWideKeyword::RevertLayer |
                    CSSWideKeyword::Revert => {
                        declaration.debug_crash("Found revert* not dealt with");
                    },
                }
                return;
            },
            #[cfg(debug_assertions)]
            PropertyDeclaration::WithVariables(..) => {
                declaration.debug_crash("Found variables not substituted");
                return;
            },
            _ => unsafe {
                declaration.unchecked_value_as::<longhands::mask_composite::SpecifiedValue>()
            },
        };


            let computed = specified_value.to_computed_value(context);
            context.builder.set_mask_composite(computed)
    }

    pub fn parse_declared<'i, 't>(
        context: &ParserContext,
        input: &mut Parser<'i, 't>,
    ) -> Result<PropertyDeclaration, ParseError<'i>> {
        parse(context, input)
            .map(PropertyDeclaration::MaskComposite)
    }

    pub mod single_value {
        use super::*;
    pub use self::computed_value::T as SpecifiedValue;
    pub mod computed_value {
        #[allow(unused_imports)]
        use crate::derives::*;
        #[derive(
            Clone,
            Copy,
            Debug,
            Deserialize,
            Eq,
            FromPrimitive,
            Hash,
            MallocSizeOf,
            Parse,
            PartialEq,
            Serialize,
            SpecifiedValueInfo,
            ToAnimatedValue,
            ToComputedValue,
            ToCss,
            ToResolvedValue,
            ToShmem,
            ToTyped,
        )]
        pub enum T {
        
        Add,
        
        Subtract,
        
        Intersect,
        
        Exclude,
        }
    }
    #[inline]
    pub fn get_initial_value() -> computed_value::T {
        computed_value::T::Add
    }
    #[inline]
    pub fn get_initial_specified_value() -> SpecifiedValue {
        SpecifiedValue::Add
    }
    #[inline]
    pub fn parse<'i, 't>(_context: &ParserContext, input: &mut Parser<'i, 't>)
                         -> Result<SpecifiedValue, ParseError<'i>> {
        SpecifiedValue::parse(input)
    }

    #[cfg(feature = "gecko")]
    impl SpecifiedValue {
        /// Obtain a specified value from a Gecko keyword value
        ///
        /// Intended for use with presentation attributes, not style structs
        pub fn from_gecko_keyword(kw: u32) -> Self {
            use crate::gecko_bindings::structs;
            // We can't match on enum values if we're matching on a u32
            const ADD: u32 = structs::StyleMaskComposite::Add as u32;
            // We can't match on enum values if we're matching on a u32
            const SUBTRACT: u32 = structs::StyleMaskComposite::Subtract as u32;
            // We can't match on enum values if we're matching on a u32
            const INTERSECT: u32 = structs::StyleMaskComposite::Intersect as u32;
            // We can't match on enum values if we're matching on a u32
            const EXCLUDE: u32 = structs::StyleMaskComposite::Exclude as u32;
            match kw {
                ADD => Self::Add,
                SUBTRACT => Self::Subtract,
                INTERSECT => Self::Intersect,
                EXCLUDE => Self::Exclude,
                _ => panic!("Found unexpected value in style struct for mask-composite property"),
            }
        }
    }
    } // single_value

    // The setup here is roughly:
    //
    //  * UnderlyingList is the list that is stored in the computed value. This may
    //    be a shared ArcSlice if the property is inherited.
    //  * UnderlyingOwnedList is the list that is used for animation.
    //  * Specified values always use OwnedSlice, since it's more compact.
    //  * computed_value::List is just a convenient alias that you can use for the
    //    computed value list, since this is in the computed_value module.
    //
    // If vector.simple_bindings is true, then we don't use the complex iterator
