    type Single = crate::properties::longhands::corner_top_left_shape::SpecifiedValue;

    fn parse_value<'i, 't>(
        context: &ParserContext,
        input: &mut Parser<'i, 't>,
    ) -> Result<Longhands, ParseError<'i>> {
        let first = <Single as crate::parser::Parse>::parse(context, input)?;
        let second =
            input.try_parse(|input| <Single as crate::parser::Parse>::parse(context, input)).unwrap_or_else(|_| first.clone());
        Ok(crate::properties::shorthands::expanded! {
            corner_top_left_shape: first,
            corner_top_right_shape: second,
        })
    }

    impl<'a> ToCss for LonghandsToSerialize<'a>  {
        fn to_css<W>(&self, dest: &mut CssWriter<W>) -> fmt::Result where W: fmt::Write {
            let first = &self.corner_top_left_shape;
            let second = &self.corner_top_right_shape;

            first.to_css(dest)?;
            if first != second {
                dest.write_char(' ')?;
                second.to_css(dest)?;
            }
            Ok(())
        }
    }

